-- =====================================================================================
-- iNXT BrokerVerse - V983 Seed accounts (seed profile only): four seed clients of our own
-- (prospect codes PR-2026-9000nn) and fifteen accounts across products and stages, with their
-- risk items, premium breakdown (Appendix A) and consistent NB_ACCOUNT work cases and status
-- history. Premiums follow the seeded rates (V811), branch LGT and commission (V982).
-- =====================================================================================
insert into crm_client (company_id, prospect_code, client_code, status, client_type, last_name,
    first_name, middle_name, corporate_name, display_name, birth_date, email, mobile, address_line,
    city, province, market_segment, bank_client, kyc_status, kyc_verified_by, kyc_verified_at,
    kyc_review_due, confirmed_by, confirmed_at, created_at, created_by)
select c.id, v.pc, v.cc, v.status, v.ctype, v.last, v.first, v.middle, v.corp, v.display, v.birth::date,
       v.email, v.mobile, v.addr, v.city, v.prov, v.seg, true, v.kyc,
       case when v.kyc = 'VERIFIED' then 'mkttl' end,
       case when v.kyc = 'VERIFIED' then timestamptz '2026-08-01 09:00:00+08' end,
       case when v.kyc = 'VERIFIED' then date '2027-08-01' end,
       case when v.status = 'CONFIRMED' then 'mkttl' end,
       case when v.status = 'CONFIRMED' then timestamptz '2026-08-01 10:00:00+08' end,
       timestamptz '2026-07-28 09:00:00+08', 'ao'
from org_company c, (values
  ('PR-2026-900001', 'CL-2026-900001', 'CONFIRMED', 'INDIVIDUAL', 'Santos', 'Maria Clara', 'Reyes', null, 'Santos, Maria Clara Reyes', '1984-03-14', 'mc.santos@example.ph', '09171230001', '22 Acacia Lane, Ayala Alabang', 'Muntinlupa', 'Metro Manila', 'CBG', 'VERIFIED'),
  ('PR-2026-900002', 'CL-2026-900002', 'CONFIRMED', 'INDIVIDUAL', 'Reyes', 'Jose Antonio', null, null, 'Reyes, Jose Antonio', '1979-11-02', 'ja.reyes@example.ph', '09171230002', '5 Banilad Road', 'Cebu City', 'Cebu', 'CBG', 'VERIFIED'),
  ('PR-2026-900003', 'CL-2026-900003', 'CONFIRMED', 'CORPORATE', null, null, null, 'Pacific Harbor Logistics Inc.', 'Pacific Harbor Logistics Inc.', null, 'risk@pacificharbor.example', '09171230003', 'Pier 12, North Harbor', 'Manila', 'Metro Manila', 'CORBANK', 'VERIFIED'),
  ('PR-2026-900004', null, 'PROSPECT', 'INDIVIDUAL', 'Villanueva', 'Ana', 'Cruz', null, 'Villanueva, Ana Cruz', '1991-07-21', 'ana.villanueva@example.ph', '09171230004', '18 Mango Avenue', 'Davao City', 'Davao del Sur', 'RETAIL', 'PENDING')
) as v(pc, cc, status, ctype, last, first, middle, corp, display, birth, email, mobile, addr,
         city, prov, seg, kyc)
where c.code = 'FVI';

